class Solution {
public:
    int maximumSum(vector<int>& arr) {
        int no_del = arr[0];
        int one_del = 0;
        int ans = arr[0];
        for (size_t i = 1; i < arr.size(); ++i) {
            int x = arr[i];
            one_del = max(no_del, one_del + x);
            no_del = max(x, no_del + x);
            ans = max({ans, no_del, one_del});
        }
        return ans;
    }
};

class Solution {
    public int maximumSum(int[] arr) {
        int no_del = arr[0];
        int one_del = 0;
        int ans = arr[0];
        for (int i = 1; i < arr.length; i++) {
            int x = arr[i];
            one_del = Math.max(no_del, one_del + x);
            no_del = Math.max(x, no_del + x);
            ans = Math.max(ans, Math.max(no_del, one_del));
        }
        return ans;
    }
}

